// appError keeps the user-facing context separate from the underlying cause.
type appError struct {
    message string
    causes []string
}
func (e *appError) Error() string { return e.message }
func failure(message string, causes ...string) error { return &appError{message, causes} }
func showError(err error) {
    if e, ok := err.(*appError); ok {
        fmt.Fprintln(os.Stderr, "Error: " + e.message)
        if len(e.causes) > 0 {
            fmt.Fprintln(os.Stderr, "\nCaused by:")
            for i, c := range e.causes {
                if len(e.causes) == 1 { fmt.Fprintln(os.Stderr, "    " + c) } else { fmt.Fprintf(os.Stderr, "    %d: %s\n", i, c) }
            }
        }
    } else { fmt.Fprintln(os.Stderr, "Error: " + err.Error()) }
}
func main() {
    initLogging()
    cfg, done, code := parseCLI(os.Args)
    if done { os.Exit(code) }
    var err error
    if cfg.mode == "server" { err = runServer(cfg) } else { err = runLocal(cfg) }
    if err != nil { showError(err); os.Exit(1) }
}
