type option struct { name, value, short, env, kind string }
var localOptions = []option{
    {"local-host", "HOST", "l", "", "string"},
    {"to", "TO", "t", "BORE_SERVER", "string"},
    {"port", "PORT", "p", "", "port"},
    {"secret", "SECRET", "s", "BORE_SECRET", "string"},
}
var serverOptions = []option{
    {"min-port", "MIN_PORT", "", "BORE_MIN_PORT", "port"},
    {"max-port", "MAX_PORT", "", "BORE_MAX_PORT", "port"},
    {"secret", "SECRET", "s", "BORE_SECRET", "string"},
    {"bind-addr", "BIND_ADDR", "", "", "ip"},
    {"bind-tunnels", "BIND_TUNNELS", "", "", "ip"},
}
func (o option) label() string { if o.name == "LOCAL_PORT" { return "<LOCAL_PORT>" }; return "--"+o.name+" <"+o.value+">" }
const footer = "\nFor more information, try '--help'.\n"
const groupLocal = "<LOCAL_PORT|--local-host <HOST>|--to <TO>|--port <PORT>|--secret <SECRET>>"
const groupServer = "<--min-port <MIN_PORT>|--max-port <MAX_PORT>|--secret <SECRET>|--bind-addr <BIND_ADDR>|--bind-tunnels <BIND_TUNNELS>>"

func basicUsage(prog, mode string) string {
    switch mode {
    case "local": return prog+" local [OPTIONS] --to <TO> <LOCAL_PORT>"
    case "server": return prog+" server [OPTIONS]"
    case "help": return prog+" help [COMMAND]..."
    default: return prog+" <COMMAND>"
    }
}
func helpText(prog, mode string) string {
    switch mode {
    case "local":
        return "Starts a local proxy to the remote server\n\nUsage: "+basicUsage(prog,mode)+"\n\nArguments:\n"+
            "  <LOCAL_PORT>  The local port to expose [env: BORE_LOCAL_PORT="+os.Getenv("BORE_LOCAL_PORT")+"]\n\nOptions:\n"+
            "  -l, --local-host <HOST>  The local host to expose [default: localhost]\n"+
            "  -t, --to <TO>            Address of the remote server to expose local ports to [env: BORE_SERVER="+os.Getenv("BORE_SERVER")+"]\n"+
            "  -p, --port <PORT>        Optional port on the remote server to select [default: 0]\n"+
            "  -s, --secret <SECRET>    Optional secret for authentication [env: BORE_SECRET]\n"+
            "  -h, --help               Print help\n"
    case "server":
        return "Runs the remote proxy server\n\nUsage: "+basicUsage(prog,mode)+"\n\nOptions:\n"+
            "      --min-port <MIN_PORT>          Minimum accepted TCP port number [env: BORE_MIN_PORT="+os.Getenv("BORE_MIN_PORT")+"] [default: 1024]\n"+
            "      --max-port <MAX_PORT>          Maximum accepted TCP port number [env: BORE_MAX_PORT="+os.Getenv("BORE_MAX_PORT")+"] [default: 65535]\n"+
            "  -s, --secret <SECRET>              Optional secret for authentication [env: BORE_SECRET]\n"+
            "      --bind-addr <BIND_ADDR>        IP address to bind to, clients must reach this [default: 0.0.0.0]\n"+
            "      --bind-tunnels <BIND_TUNNELS>  IP address where tunnels will listen on, defaults to --bind-addr\n"+
            "  -h, --help                         Print help\n"
    case "help":
        return "Print this message or the help of the given subcommand(s)\n\nUsage: "+basicUsage(prog,mode)+"\n\nArguments:\n  [COMMAND]...  Print help for the subcommand(s)\n"
    default:
        return "A modern, simple TCP tunnel in Rust that exposes local ports to a remote server, bypassing standard NAT connection firewalls.\n\nUsage: "+basicUsage(prog,"")+"\n\nCommands:\n"+
            "  local   Starts a local proxy to the remote server\n"+
            "  server  Runs the remote proxy server\n"+
            "  help    Print this message or the help of the given subcommand(s)\n\nOptions:\n"+
            "  -h, --help     Print help\n  -V, --version  Print version\n"
    }
}

type cliParser struct {
    prog, mode string
    opts []option
    values map[string]string
    order []string
    explicit map[string]bool
}
func (p *cliParser) err(text string) (config, bool, int) { fmt.Fprint(os.Stderr, text); return config{}, true, 2 }
func (p *cliParser) diagnostic(text, usage string) (config, bool, int) {
    if usage != "" { text += "\n\nUsage: "+usage+"\n" } else { text += "\n" }
    return p.err("error: "+text+footer)
}
func (p *cliParser) find(name string, short bool) (option,bool) {
    if (!short && name == "help") || (short && name == "h") { return option{"help","","h","","flag"},true }
    if p.mode=="" && ((!short && name=="version") || (short && name=="V")) {return option{"version","","V","","flag"},true}
    for _, o := range p.opts { if (!short && name==o.name) || (short && name==o.short) { return o,true } }
    return option{},false
}
func (p *cliParser) optsUsage(include string) string {
    s:=p.prog
    if p.mode != "" { s+=" "+p.mode }
    if p.mode=="local" { s+=" --to <TO>" }
    for _, name := range p.order {
        if name=="to" || name=="LOCAL_PORT" {continue}
        o,_:=p.find(name,false); s+=" "+o.label()
    }
    if include!="" { s+=" --"+include }
    if p.mode=="local" { s+=" <LOCAL_PORT>" } else if p.mode=="" {s+=" <COMMAND>"}
