}
func (p *cliParser) unknownArg(arg string, long bool) (config,bool,int) {
    text:="unexpected argument '"+arg+"' found"
    usage:=basicUsage(p.prog,p.mode)
    suggestion:=""
    if long {
        var names []string
        for _,o:=range p.opts { names=append(names,o.name) }
        names=append(names,"help")
        if p.mode=="" {names=append(names,"version")}
        suggestion=closest(strings.TrimPrefix(arg,"--"),names)
    }
    if suggestion!="" {
