    } else if p.mode=="local" && strings.HasPrefix(arg,"-") && arg!="-" {
        text+="\n\n  tip: to pass '"+arg+"' as a value, use '-- "+arg+"'"
    }
    if long && (suggestion!="" || len(p.order)>0) {
