func validate(o option,v string) string {
    switch o.kind {
    case "port":
        why:=""
        if v=="" { why="cannot parse integer from empty string" } else {
            n,err:=strconv.ParseInt(v,10,64)
            if err!=nil {
                if ne,ok:=err.(*strconv.NumError);ok && ne.Err==strconv.ErrRange {
