    case "ip":
        a,err:=netip.ParseAddr(v)
        if err!=nil || a.Zone()!="" { return "invalid value '"+v+"' for '"+o.label()+"': invalid IP address syntax" }
    }
    return ""
}
func parseCLI(args []string) (config,bool,int) {
    prog:=filepath.Base(args[0]); if prog=="." || prog=="/" || prog=="" { prog="bore-cli" }
    p:=&cliParser{prog:prog,values:map[string]string{},explicit:map[string]bool{}}
